package com.logiplatform.model;

import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;

@Entity @Table(name="road_consignments") public class RoadConsignment { @Id @GeneratedValue UUID id; @Column(name="tenant_id",nullable=false,updatable=false) UUID tenantId; @Column(name="shipment_id",nullable=false) UUID shipmentId; String cmrNumber,vehicleRegistration,trailerRegistration,driverName,driverPhone; Instant pickupWindowStart,pickupWindowEnd,deliveryWindowStart,deliveryWindowEnd; String status="PLANNED"; UUID podDocumentId; Instant createdAt=Instant.now(),updatedAt=Instant.now(); protected RoadConsignment(){} public RoadConsignment(UUID t,UUID s,String cmr,String vehicle,String trailer,String driver,String phone){tenantId=t;shipmentId=s;cmrNumber=cmr;vehicleRegistration=vehicle;trailerRegistration=trailer;driverName=driver;driverPhone=phone;} public UUID getId(){return id;} public UUID getShipmentId(){return shipmentId;} public String getCmrNumber(){return cmrNumber;} public String getVehicleRegistration(){return vehicleRegistration;} public String getTrailerRegistration(){return trailerRegistration;} public String getDriverName(){return driverName;} public String getStatus(){return status;} }
